// Example: idempotent checkout invocation
async function runIdempotentCheckout(key) {
  const first = await checkout.perform({ amount: 1000, customerId: 'C1' }, key);
  const second = await checkout.perform({ amount: 1000, customerId: 'C1' }, key);
  if (first.orderId !== second.orderId) throw new Error('Non-idempotent');
}
```

